var readTextFile=function(file,label,limitBytes){var limit=limitBytes||1024*1024;if(file.size>limit){return Promise.reject(new Error(label+" exceeds the "+(limit===1024*1024?"1 MiB":"8 MiB")+" limit"))}return new Promise(function(resolve,reject){var reader=new FileReader();reader.onerror=function(){reject(new Error("unable to read file"))};reader.onabort=reader.onerror;reader.onload=function(){resolve(String(reader.result||""))};reader.readAsText(file)})};
